#include <stdio.h>

long fib_cached(int n) {
    static long cache[50];
    static int have[50];
    if (n < 2) return n;
    if (have[n]) return cache[n];
    long r = fib_cached(n - 1) + fib_cached(n - 2);
    cache[n] = r;
