int main(void)
{
    int c;
    int negative_count = 0;
    int total = 0;
    while ((c = getchar()) != EOF) {
        char ch = (char)c;
        if (ch < 0) {
            negative_count++;
        }
        total++;
    }
    printf("%d %d\n", total, negative_count);
    return 0;
}

