/* ---- dosya: parser.c ---- */
#include <string.h>
#include <ctype.h>
#include "config.h"

static void trim(char *s)
{
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r' || s[len - 1] == ' ')) {
        s[--len] = '\0';
    }
    size_t start = 0;
    while (s[start] == ' ') start++;
    if (start > 0) {
        memmove(s, s + start, strlen(s + start) + 1);
    }
}

/* "key=value" satirlarindan olusan metni ayristirir; bos satirlari ve
 * '#' ile baslayan yorum satirlarini atlar. Doldurulan giris sayisini
 * dondurur. */
int parse_config_lines(const char *text, ConfigEntry entries[], int max_entries)
{
    int count = 0;
    const char *p = text;
    char line[MAX_KEY_LEN + MAX_VAL_LEN + 4];

    while (*p && count < max_entries) {
        size_t i = 0;
        while (*p && *p != '\n' && i < sizeof(line) - 1) {
            line[i++] = *p++;
        }
        line[i] = '\0';
        if (*p == '\n') p++;

        trim(line);
        if (line[0] == '\0' || line[0] == '#') {
            continue;
        }

        char *eq = strchr(line, '=');
        if (!eq) {
            continue;
        }
        *eq = '\0';
        char *key = line;
        char *value = eq + 1;
        trim(key);
        trim(value);

        strncpy(entries[count].key, key, MAX_KEY_LEN - 1);
        entries[count].key[MAX_KEY_LEN - 1] = '\0';
        strncpy(entries[count].value, value, MAX_VAL_LEN - 1);
        entries[count].value[MAX_VAL_LEN - 1] = '\0';
        count++;
    }
    return count;
}


/* ---- dosya: lookup.c ---- */
#include <string.h>
#include "config.h"

/* key'i bulursa value'ya isaretci dondurur; bulamazsa NULL. */
const char *config_lookup(const ConfigEntry entries[], int count, const char *key)
{
    for (int i = 0; i < count; i++) {
        if (strcmp(entries[i].key, key) == 0) {
            return entries[i].value;
        }
    }
    return NULL;
}


/* ---- dosya: main.c ---- */
#include <stdio.h>
#include <string.h>
#include "config.h"

/* Girdi bicimi:
 *   N (config satiri sayisi)
 *   N satir "key=value" (veya bos/# yorum satiri)
 *   M (sorgu sayisi)
 *   M satir key
 * Her sorgu icin value ya da "NOT_FOUND" yazdirilir. */
int main(void)
{
    int n;
    if (scanf("%d", &n) != 1) return 1;
    getchar();

    char text[4096] = {0};
    size_t used = 0;
    char line[256];
    for (int i = 0; i < n; i++) {
        if (!fgets(line, sizeof(line), stdin)) break;
        size_t l = strlen(line);
        if (used + l < sizeof(text) - 1) {
            memcpy(text + used, line, l);
            used += l;
        }
    }
    text[used] = '\0';

    ConfigEntry entries[MAX_ENTRIES];
    int count = parse_config_lines(text, entries, MAX_ENTRIES);

    int m;
    if (scanf("%d", &m) != 1) return 1;
    for (int i = 0; i < m; i++) {
        char key[MAX_KEY_LEN];
        if (scanf("%31s", key) != 1) break;
        const char *val = config_lookup(entries, count, key);
        printf("%s\n", val ? val : "NOT_FOUND");
    }
    return 0;
}


